const roles=(await (await fetch(`${base}/roles?fields=name,id`,{headers:H})).json()).data;
console.log("roles:", roles.map(r=>r.name).join(","));
const users=(await (await fetch(`${base}/users?fields=email,provider&limit=10`,{headers:H})).json()).data;
console.log("users:", users.map(u=>u.email+"("+u.provider+")").join(", "));
